import * as commentService from '../services/comment';

export default {
    namespace: 'comment',
    state: {
        list: [],
        total: null,
        page: null,
    },
    reducers: {
        save(state, {payload}) {
            const {data : list , total, page} = payload ;
            return {...state, list, total, page};
        },
    },
    effects: {
        *fetch({payload: {page = 1}}, {call, put}) {
            const {data, headers} = yield call(commentService.fetch, {page});
            // TODO 此处可以查看异步请求的数据格式哦 然后根据格式解析payload  console.log(data) ;
            yield put({
                type: 'save',
                payload: {
                    data:data.data,
                    total: parseInt(headers['x-total-count'], 10), // 此header头 在util/request.js 中被填充了
                    page: parseInt(page, 10),
                },
            });
        },
        *remove({payload: id}, {call, put}) {
            yield call(commentService.remove, id);
            yield put({type: 'reload'});
        },
        *patch({payload: {id, values}}, {call, put}) {
            yield call(commentService.patch, id, values);
            yield put({type: 'reload'});
        },
        *create({payload: values}, {call, put}) {
            yield call(commentService.create, values);
            yield put({type: 'reload'});
        },
        *reload(action, {put, select}) {
            const page = yield select(state => state.comment.page);
            yield put({type: 'fetch', payload: {page}});
        },
    },
    subscriptions: {
        setup({dispatch, history}) {
            return history.listen(({pathname, query}) => {
                if (pathname === '/comment') {
                    dispatch({type: 'fetch', payload: query});
                }
            });
        },
    },
};

var gulp = require('gulp'),
	plumber = require('gulp-plumber'),
	sass = require('gulp-sass'),
	concat = require('gulp-concat'),
	uglify = require('gulp-uglify'),
	notify = require('gulp-notify'),
	bourbon = require('node-bourbon').includePaths,
	neat = require('node-neat').includePaths,
	watch = require('gulp-watch'),
	notify = require('gulp-notify'),
	csso = require('gulp-csso'),
	shorthand = require('gulp-shorthand'),
	autoprefixer = require('gulp-autoprefixer'),
	jshint = require('gulp-jshint'),
	runSequence = require('run-sequence'),
	riot = require('gulp-riot'),
	browserSync = require('browser-sync').create()
    normalize = require('node-normalize-scss').includePaths;

var paths = {
	scss: './resources/scss/**/*.scss',
	css: './public/assets/css',
	jsSrc: './resources/js/**/*.js',
	js: './public/assets/js',
	riot: './resources/riot/**/*.tag'
};

gulp.task('browser-sync', function () {
    browserSync.init({
        logPrefix: 'New England Fertility',
        proxy:     'newenglandfertility.app',
        port:      4073,
        notify:    false,
        open: 	   'external',
        ghost:     false,
        // Change this property with files of your project
        // that you want to refresh the page on changes.
        files:     [
            './**/*.php',
            './public/content/**/*.txt'
        ]
    });
});

gulp.task('sass', function () {
  return gulp.src(paths.scss)
    .pipe(plumber({errorHandler: notify.onError("SASS error: <%= error.message %> in <%= error.filename %>")}))
    .pipe(sass({
        includePaths: [].concat(bourbon, neat, normalize),
        outputStyle: 'expanded'
    }))
    .pipe(shorthand())
    .pipe(csso())
    .pipe(autoprefixer({
        browsers: ['> 1%'],
        cascade: false
    }))
    .pipe(gulp.dest(paths.css))
    .pipe( browserSync.stream() );
});

gulp.task('uglify', function() {
    return gulp.src(paths.jsSrc)
        .pipe(plumber({errorHandler: notify.onError("JS uglification error: <%= error.message %>")}))
        .pipe(jshint())
        .pipe(jshint.reporter('jshint-stylish'))
        .pipe(uglify())
        .pipe(gulp.dest(paths.js))
        .pipe( browserSync.stream() );
});

gulp.task('riot', function() {
    return gulp.src(paths.riot)
        .pipe(plumber({errorHandler: notify.onError("Riot compilation error: <%= error.message %>")}))
        .pipe(riot({
            compact: true
        }))
        .pipe(concat('tags.js'))
        .pipe(uglify())
        .pipe(gulp.dest(paths.js))
        .pipe( browserSync.stream() );
});

gulp.task('build', function() {
  runSequence('sass','uglify','riot');
});

gulp.task('watch', function() {
  gulp.watch(paths.scss, ['sass']);
  gulp.watch(paths.jsSrc, ['uglify']);
  gulp.watch(paths.riot, ['riot']);
});

gulp.task('default', function () {
  runSequence('browser-sync');
  gulp.watch(paths.scss, ['sass']);
  gulp.watch(paths.jsSrc, ['uglify']);
  gulp.watch(paths.riot, ['riot']);
});

